<body>
<main>
  <h1>Crear una cuenta</h1>
  <p class="intro">Todos los campos son obligatorios.</p>

  <p class="exito" id="mensaje-exito" role="status" tabindex="-1"></p>

  <!--
    Añade un atributo "action" con la URL de tu servidor para enviar los datos de verdad.
    Sin "action", la página funciona en modo demostración y solo muestra un mensaje de confirmación.
  -->
  <form id="registro" method="post" novalidate>
    <div class="campo">
      <label for="nombre">Nombre completo</label>
      <input type="text" id="nombre" name="nombre" autocomplete="name" maxlength="100"
             required aria-required="true" aria-describedby="nombre-error">
      <p class="error" id="nombre-error" hidden></p>
    </div>

    <div class="campo">
      <label for="email">Correo electrónico</label>
      <input type="email" id="email" name="email" autocomplete="email" inputmode="email"
             maxlength="254" placeholder="nombre@ejemplo.com"
             required aria-required="true" aria-describedby="email-error">
      <p class="error" id="email-error" hidden></p>
    </div>

    <div class="campo">
      <label for="web">Sitio web</label>
      <input type="url" id="web" name="web" autocomplete="url" inputmode="url"
             maxlength="2000" placeholder="https://www.ejemplo.com"
             required aria-required="true" aria-describedby="web-error">
      <p class="error" id="web-error" hidden></p>
    </div>

    <div class="campo">
      <label for="password">Contraseña</label>
      <div class="con-boton">
        <input type="password" id="password" name="password" autocomplete="new-password"
               maxlength="128" required aria-required="true"
               aria-describedby="password-ayuda password-error">
        <button type="button" class="alternar" id="alternar-password"
                aria-controls="password" aria-pressed="false">Mostrar</button>
      </div>
      <p class="ayuda" id="password-ayuda">Mínimo 8 caracteres, con al menos una letra y un número.</p>
      <p class="error" id="password-error" hidden></p>
    </div>

    <button type="submit">Registrarse</button>
  </form>
</main>

<script>
(function () {
  'use strict';

  var form = document.getElementById('registro');
  var mensajeExito = document.getElementById('mensaje-exito');
  var botonAlternar = document.getElementById('alternar-password');
  var nombresCampos = ['nombre', 'email', 'web', 'password'];

  /* Añade "https://" si el usuario escribió la dirección sin protocolo. */
  function normalizarUrl(valor) {
    var v = valor.trim();
    if (v && !/^[a-z][a-z0-9+.-]*:\/\//i.test(v)) {
      v = 'https://' + v;
    }
    return v;
  }

  /* Cada validador devuelve un mensaje de error, o una cadena vacía si el valor es válido. */
  var validadores = {
    nombre: function (valor) {
      var v = valor.trim().replace(/\s+/g, ' ');
      if (!v) return 'Introduce tu nombre completo.';
      if (v.length < 2) return 'El nombre debe tener al menos 2 caracteres.';
      if (!/^[\p{L}\p{M}'’.\- ]+$/u.test(v) || !/\p{L}/u.test(v)) {
        return 'El nombre solo puede contener letras, espacios, guiones y apóstrofos.';
      }
      return '';
    },

    email: function (valor) {
      var v = valor.trim();
      if (!v) return 'Introduce tu correo electrónico.';
      if (v.length > 254 || !/^[^\s@]+@[^\s@.]+(\.[^\s@.]+)+$/.test(v)) {
        return 'Introduce un correo válido, por ejemplo nombre@ejemplo.com.';
      }
      return '';
    },

    web: function (valor) {
      var v = normalizarUrl(valor);
      if (!v) return 'Introduce la dirección de tu sitio web.';
      var url;
      try {
        url = new URL(v);
      } catch (e) {
        return 'Introduce una dirección válida, por ejemplo https://www.ejemplo.com.';
      }
      if (url.protocol !== 'http:' && url.protocol !== 'https:') {
        return 'La dirección debe empezar por http:// o https://.';
      }
      var dominioValido =
        /^(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z][a-z0-9-]{0,61}[a-z0-9]$/i.test(url.hostname);
      if (!dominioValido || url.username || url.password) {
        return 'Introduce una dirección válida, por ejemplo https://www.ejemplo.com.';
      }
      return '';
    },

    password: function (valor) {
      if (!valor) return 'Introduce una contraseña.';
      if (valor.length < 8) return 'La contraseña debe tener al menos 8 caracteres.';
      if (!/\p{L}/u.test(valor) || !/\d/.test(valor)) {
        return 'La contraseña debe incluir al menos una letra y un número.';
      }
      return '';
    }
  };

  function mostrarError(campo, mensaje) {
    var error = document.getElementById(campo.id + '-error');
    error.textContent = mensaje;
    error.hidden = !mensaje;
    if (mensaje) {
      campo.setAttribute('aria-invalid', 'true');
    } else {
      campo.removeAttribute('aria-invalid');
    }
  }

  function validarCampo(campo) {
    var mensaje = validadores[campo.id](campo.value);
    mostrarError(campo, mensaje);
    return !mensaje;
  }

  nombresCampos.forEach(function (id) {
    var campo = document.getElementById(id);

    /* Al salir del campo: normalizar y validar. */
    campo.addEventListener('blur', function () {
      if (id === 'web') campo.value = normalizarUrl(campo.value);
      if (id === 'nombre') campo.value = campo.value.trim().replace(/\s+/g, ' ');
      validarCampo(campo);
    });

    /* Mientras se escribe: revalidar solo si el campo ya mostraba un error. */
    campo.addEventListener('input', function () {
      mensajeExito.textContent = '';
      if (campo.getAttribute('aria-invalid') === 'true') {
        validarCampo(campo);
      }
    });
  });

  botonAlternar.addEventListener('click', function () {
    var campo = document.getElementById('password');
    var visible = campo.type === 'text';
    campo.type = visible ? 'password' : 'text';
    botonAlternar.textContent = visible ? 'Mostrar' : 'Ocultar';
    botonAlternar.setAttribute('aria-pressed', String(!visible));
  });

  form.addEventListener('submit', function (evento) {
    var primerInvalido = null;
    mensajeExito.textContent = '';

    var campoWeb = document.getElementById('web');
    campoWeb.value = normalizarUrl(campoWeb.value);

    nombresCampos.forEach(function (id) {
      var campo = document.getElementById(id);
      if (!validarCampo(campo) && !primerInvalido) {
        primerInvalido = campo;
      }
    });

    if (primerInvalido) {
      evento.preventDefault();
      primerInvalido.focus();
      return;
    }

    /* Formulario válido: si hay un "action" definido, el navegador lo envía normalmente. */
    if (form.hasAttribute('action')) return;

    /* Modo demostración (sin "action"): se confirma en la propia página. */
    evento.preventDefault();
    var nombre = document.getElementById('nombre').value.trim().replace(/\s+/g, ' ');
    form.reset();
    document.getElementById('password').type = 'password';
    botonAlternar.textContent = 'Mostrar';
    botonAlternar.setAttribute('aria-pressed', 'false');
    mensajeExito.textContent = '¡Gracias, ' + nombre + '! Tus datos son válidos y el registro se ha completado.';
    mensajeExito.focus();
  });
})();
</script>
</body>
